INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68873, 'spa', 'Gobierno o reinado', 'Lucas emplea este término en Lucas 3:1, fechando el ministerio de Juan en el año decimoquinto del reinado de Tiberio. El uso clásico incluía mando militar, supremacía política y liderazgo institucional. Al elegir esta palabra en lugar de términos más sencillos, Lucas subraya el ejercicio activo y formal de la autoridad imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68874, 'spa', 'Gobernador', 'Gobernador: El sentido dominante en el NT: un gobernador provincial romano que ejerce autoridad judicial y administrativa. Todos los relatos sinópticos de la Pasión usan ἡγεμών para Pilato (Mt 27:2, 11, 14-15), y Hechos lo aplica a Félix y Festo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68876, 'spa', 'Gobernadores', 'Gobernadores: La forma plural, usada cuando Jesús o los apóstoles hablan de manera genérica sobre las autoridades civiles ante las cuales los creyentes testificarán. Mt 10:18 y Mc 13:9 emparejan ἡγεμόνες con reyes como poderes representativos del estado. Primera de Pedro 2:14 sitúa a los gobernadores junto al emperador en una jerarquía de autoridad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68877, 'spa', 'Gobernantes', 'Gobernantes: Un sentido más amplio de ''gobernante'' o ''líder'', aplicado proféticamente en Mt 2:6 a aquel que pastoreará a Israel. Aquí Mateo cita Miqueas 5:2, y la palabra lleva peso mesiánico en lugar de connotaciones burocráticas romanas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68879, 'spa', 'El sentido cognitivo', 'El sentido cognitivo: considerar, pensar, estimar o tener algo por cierto. Pablo lo emplea para evaluar sus antiguos privilegios como pérdida (Fil 3:7-8), para exhortar a la estima mutua (Fil 2:3) y para expresar su juicio meditado (2 Co 9:5; Hch 26:2). Santiago 1:2 lo usa para contar las pruebas como gozo. Capta una evaluación deliberada y reflexiva, no una opinión superficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68880, 'spa', 'El sentido de liderazgo', 'El sentido de liderazgo: dirigir, guiar o gobernar a otros. Mateo 2:6 lo aplica al gobernante mesiánico de Belén (citando Miq 5:2), Hechos 7:10 a José como gobernador de Egipto, y Hechos 14:12 a Bernabé como figura ''principal''. Hebreos 13:7, 17, 24 emplea el participio como término casi técnico para los líderes de la iglesia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68896, 'spa', 'Gustosamente, con agrado', 'Este sentido transmite un compromiso voluntario y complacido, no un deber a regañadientes. Los tres contextos neotestamentarios implican escuchar o recibir las palabras de alguien: la fascinación conflictiva de Herodes con el Bautista, la recepción entusiasta de la enseñanza de Jesús por las multitudes, y la tolerancia quizá excesiva de la iglesia corintia hacia los falsos apóstoles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68897, 'spa', 'Ya, a estas alturas', 'Adverbio temporal que indica que algo ha ocurrido o un estado se ha alcanzado para el momento presente, frecuentemente con el matiz de que ha sucedido antes de lo anticipado. Pasajes clave incluyen la declaración de Jesús de que mirar con lujuria ''ya'' constituye adulterio (Mt 5:28) y la observación de los discípulos de que la tarde ''ya'' ha llegado (Mt 14:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68899, 'spa', 'Placer pernicioso', 'Placer sensual o deseo autocomplaciente, presentado en el NT como espiritualmente destructivo. En Lc 8:14 los placeres ahogan la palabra junto con las riquezas y los afanes; Tit 3:3 recuerda una vida pasada esclavizada a diversos placeres; Stg 4:1 identifica los placeres que batallan en los miembros como fuente de contiendas; Stg 4:3 denuncia la oración corrompida por el afán de gastar en placeres; y 2 Pe 2:13 condena a quienes se deleitan en sus engaños.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68901, 'spa', 'Costumbres y carácter', 'La cita de Menandro que Pablo emplea subraya cómo la asociación habitual moldea el carácter moral. El término abarca patrones de conducta exteriores y disposiciones interiores. En el uso clásico iba desde los hábitats de las criaturas hasta los rasgos de carácter de las personas. Las glosas en español (''costumbres'') y francés (''mœurs'') captan su dimensión moral-conductual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68902, 'spa', 'Haber llegado, arribar y estar presente, con el matiz de llegada consumada que c', 'Haber llegado, arribar y estar presente, con el matiz de llegada consumada que caracteriza a este verbo incluso en formas de tiempo presente. Se usa para personas que llegan de tierras lejanas (Mt 8:11), el juicio que alcanza a una generación (Mt 23:36), amos que regresan inesperadamente en las parábolas (Mt 24:50; Lc 12:46), el que ha de venir y no tardará (Heb 10:37), y el advenimiento escatológico de Cristo (Ap 2:25; 3:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68913, 'spa', 'Nombre propio genealógico', 'Lucas 3:23 identifica a Helí como padre de José en la genealogía ascendente que remonta el linaje de Jesús hasta Adán. La conexión hebrea con ''Elí'' sugiere significados relacionados con Dios o la elevación. Los traductores mantienen la forma fonética con ajustes menores según cada lengua. Su ubicación genealógica genera una conocida divergencia con Mateo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68914, 'spa', 'Nombre propio Ēlías (Elías) que designa al profeta tisbita, usado en el NT tanto', 'Nombre propio Ēlías (Elías) que designa al profeta tisbita, usado en el NT tanto como referencia histórica como figura tipológica. La tradición sinóptica lo vincula a la expectativa mesiánica (Mt 17:10-12, Mr 9:11-13), a la teofanía de la Transfiguración (Mt 17:3-4) y al grito desde la cruz confundido con una invocación a Elías (Mt 27:47, Mr 15:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68916, 'spa', 'Estatura, altura corporal', 'Estatura o altura física, la medida de cuán alto se yergue una persona. Lucas 2:52 registra que Jesús ''crecía en estatura (ἡλικία) y gracia''; Lucas 19:3 explica que Zaqueo no podía ver a Jesús por ser ''pequeño de estatura''; y Efesios 4:13 contempla a la iglesia alcanzando ''la medida de la estatura de la plenitud de Cristo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68917, 'spa', 'Edad, etapa de vida', 'Edad, madurez o etapa de la vida alcanzada en años. En Juan 9:21, 23 los padres del ciego de nacimiento dicen ''tiene edad (ἡλικίαν ἔχει), pregúntenle a él'', refiriéndose a la mayoría de edad legal. Hebreos 11:11 dice que Sara recibió fuerza para concebir ''fuera del tiempo de la edad'', aludiendo a que había superado la edad fértil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68922, 'spa', 'Magnitud relativa', 'Expresa magnitud mediante pregunta o exclamación, donde la escala concreta (grande o pequeña) depende del contexto. En Santiago 3:5 aparece dos veces en un solo versículo: primero para la pequeñez del fuego, luego para la grandeza del bosque, mostrando que su significado se determina enteramente por aquello que modifica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68923, 'spa', 'sol (el cuerpo celeste) — El sol como astro, fuente de luz y calor, con rica ext', 'sol (el cuerpo celeste) — El sol como astro, fuente de luz y calor, con rica extensión metafórica. Se usa literalmente para el amanecer y el atardecer (Mt 5:45; Mr 1:32; Ef 4:26) y como símil de gloria radiante: el rostro de Jesús en la Transfiguración (Mt 17:2), los justos en el reino (Mt 13:43), el ángel de Apocalipsis 10:1. El oscurecimiento apocalíptico del sol señala conmoción cósmica (Mt 24:29; Ap 6:12; 8:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68926, 'spa', 'día', 'Un día como unidad de tiempo (388 veces) — ya sea un día específico del calendario, un período contado o un día señalado de importancia especial. Abarca referencias temporales ordinarias («al tercer día»), períodos extendidos («en los días de Herodes») y el uso escatológico («el día del Señor»). Todas las traducciones convergen en un solo término: español «día», francés jour, alemán Tag. La amplitud es enorme, desde lo cotidiano hasta lo apocalíptico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68928, 'spa', 'luz del día, tiempo diurno', 'La luz diurna o el tiempo de día en contraste con la noche (3 veces). Se distingue del sentido de día calendario por el contraste explícito con la oscuridad. En Jn 11:9, Jesús pregunta: «¿No tiene el día doce horas?» — ἡμέρα aquí designa las horas iluminadas por el sol para caminar con seguridad. Pablo recoge esta imagen en 1 Ts 5:5, 8, donde los creyentes son «hijos del día» (no de la noche ni de las tinieblas).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68933, 'spa', 'Nuestro, posesivo plural', 'Pronombre posesivo de primera persona plural que significa ''nuestro'', enfatizando pertenencia compartida o identidad comunitaria. Más enfático que el simple genitivo ἡμῶν. En Pentecostés la multitud exclama ''los oímos en nuestras propias lenguas'' (Hch 2:11), donde ἡμετέραις subraya la conexión personal con el idioma nativo. Pablo lo usa para reclamar herencia religiosa común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68937, 'spa', 'Medio muerto', 'Jesús emplea este descriptor en Lucas 10:30 para enfatizar el peligro extremo del viajero tras el ataque de los ladrones. La construcción compuesta intensifica la vulnerabilidad de la víctima a quien el sacerdote y el levita pasan de largo. Las glosas multilingües preservan la imagen de ''medio muerto'' (medio-muerto, à-demi-mort), demostrando su fuerza expresiva intercultural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68938, 'spa', 'Mitad, medio', 'Mitad, una de dos porciones iguales, aplicada a posesiones, territorios y períodos de tiempo. En Mr 6:23 Herodes promete hasta la mitad de su reino; en Lc 19:8 Zaqueo da la mitad de sus bienes a los pobres. Los pasajes apocalípticos de Apocalipsis lo emplean para mediciones proféticas del tiempo: los testigos yacen muertos tres días y medio (Ap 11:9, 11), y la mujer es sustentada por un tiempo, tiempos y medio tiempo (Ap 12:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68939, 'spa', 'Media hora literal', 'Apocalipsis 8:1 marca una pausa dramática en la secuencia apocalíptica cuando el silencio llena el cielo por media hora tras la apertura del séptimo sello. Esta medida precisa crea suspenso y enfatiza la trascendencia de lo que sigue. Los equivalentes multilingües (media-hora, halbe-Stunde) confirman que los traductores lo interpretaron como un marcador temporal literal y no simbólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68941, 'spa', 'Comparación enfática', 'En Juan 12:43, esta partícula enfática aparece en la observación de Jesús sobre los dirigentes que amaban la gloria humana más que la gloria de Dios. La comparación intensificada subraya la trágica inversión de valores: preferir lo temporal sobre lo eterno, lo creado sobre el Creador. El uso clásico muestra la partícula añadiendo énfasis en contextos poéticos y retóricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68942, 'spa', 'Amabilidad pastoral', 'Pablo instruye a Timoteo en 2 Timoteo 2:24 que el siervo del Señor debe ser amable con todos, situado entre la disposición a enseñar y la paciencia. Los paralelos clásicos muestran el vocablo describiendo padres bondadosos, dioses misericordiosos y fuerzas naturales suaves. La evidencia multilingüe («amable», «sanft») enfatiza la cualidad tierna y no severa. Esta amabilidad no implica permisividad sino la bondad paciente propia de la madurez espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68943, 'spa', 'Nombre propio genealógico', 'Lucas 3:28 incluye a Er en la genealogía ascendente que traza el linaje de Jesús a través de José hasta Adán y finalmente hasta Dios. La raíz hebrea sugiere vigilancia o estado de alerta. Las versiones multilingües mantienen la forma fonética del nombre con ligeras variaciones. El homónimo de Génesis fue el hijo de Judá que murió bajo juicio divino, pero la ubicación genealógica indica que se trata de un Er diferente en la línea ancestral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68944, 'spa', 'Vida tranquila', 'En 1 Timoteo 2:2, Pablo insta a orar por los gobernantes para que los creyentes puedan vivir vidas tranquilas y pacíficas caracterizadas por la piedad y la dignidad. El término aparece junto a ἡσύχιος (quieto, pacífico), reforzando la imagen de una existencia serena. No se trata de escapismo sino del deseo legítimo de estabilidad social que permita al evangelio florecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68945, 'spa', 'Herodes (nombre propio) — El nombre dinástico Ἡρῴδης, aplicado a tres gobernante', 'Herodes (nombre propio) — El nombre dinástico Ἡρῴδης, aplicado a tres gobernantes neotestamentarios: Herodes el Grande en el nacimiento de Jesús (Mt 2:1-19), Herodes Antipas que decapitó al Bautista (Mr 6:14-28) y se burló de Jesús (Lc 23:7-12), y Herodes Agripa I que persiguió a la iglesia primitiva (Hch 12:1-23). El contexto determina a cuál gobernante se refiere.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68948, 'spa', 'Partido político herodiano', 'Designa un grupo político específico de la época de Jesús. Su constante asociación con los fariseos —aliados improbables dadas sus orientaciones teológicas y políticas opuestas— revela la amenaza que Jesús suponía para diversas estructuras de poder. Los fariseos rechazaban la acomodación a Roma; los herodianos dependían de ella, pero ambos veían a Jesús como peligroso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68949, 'spa', 'Herodías, personaje histórico', 'Herodías, figura histórica nieta de Herodes el Grande, originalmente casada con Herodes Felipe y luego esposa de Herodes Antipas. Guardaba rencor contra Juan el Bautista por condenar su matrimonio ilícito (Mr 6:19) y aprovechó la ocasión de la danza de su hija para exigir su cabeza en una bandeja (Mt 14:6-8, Mr 6:22-25). Lucas 3:19 resume la reprensión de Herodes «por causa de Herodías».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68950, 'spa', 'Cristiano saludado en Roma', 'Romanos 16:11 registra el saludo de Pablo a Herodión, a quien llama συγγενῆ μου (mi pariente). El nombre derivado de Herodes era común en el siglo I, reflejando la prominencia cultural de la dinastía sin implicar necesariamente lealtad política. La designación ''pariente'' ubica a Herodión entre los contactos judeocristianos de Pablo en Roma. Las transliteraciones multilingües preservan la forma griega del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68951, 'spa', 'Nombre propio del profeta del AT Isaías (hebreo יְשַׁעְיָהוּ, ''Yahvé es salvació', 'Nombre propio del profeta del AT Isaías (hebreo יְשַׁעְיָהוּ, ''Yahvé es salvación''), citado casi exclusivamente en fórmulas introductorias de citas a lo largo de los Evangelios, Hechos y Pablo (Mt 3:3; 4:14; Ro 9:27; 10:16, 20). Transliterado de manera uniforme como Isaías en español, confirmando una referencia estable de nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68952, 'spa', 'Figura bíblica Esaú', 'Se refiere a la figura histórica y teológica del Génesis. Los tres usos neotestamentarios invocan a Esaú como ejemplo en la argumentación teológica: Romanos lo emplea en la discusión sobre la soberanía de Dios, mientras que Hebreos lo menciona tanto al recibir la bendición (capítulo de la fe) como al rechazar su primogenitura (capítulo de advertencia).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68953, 'spa', 'Callar y reposar', 'Guardar silencio, descansar o permanecer callado, abarcando tanto el cese de la palabra como el de la actividad. En Lc 14:4 los doctores de la ley callan ante el desafío de Jesús; en Lc 23:56 las mujeres descansan en el sábado conforme al mandamiento; en Hch 11:18 y 21:14 los creyentes enmudecen en aquiescencia ante la voluntad de Dios, reconociendo que no pueden objetar más; y en 1 Ts 4:11 Pablo exhorta a los creyentes a llevar una vida tranquila.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68954, 'spa', 'Quietud y silencio', 'Quietud, silencio o compostura apacible, abarcando desde el hondo silencio de una multitud hasta una disposición interior de calma. Cuando la turba de Jerusalén oye a Pablo hablar en hebreo, guardan aún mayor silencio (Hch 22:2). Pablo instruye a los tesalonicenses a trabajar con sosiego en vez de entrometerse (2 Ts 3:12). En 1 Timoteo 2:11-12 el término describe la actitud receptiva y serena apropiada para el aprendizaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68956, 'spa', 'Disyunción alternativa', 'En Romanos 6:16, Pablo utiliza esta partícula disyuntiva para enmarcar la elección tajante: toda persona sirve o al pecado o a la obediencia, con sus respectivas consecuencias. La construcción elimina la neutralidad: no existe una tercera opción. La retórica clásica empleaba estas alternativas claras para forzar una decisión. Las traducciones multilingües (''sea'', ''soit...soit'', ''entweder'') reflejan esta estructura de alternativa excluyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68957, 'spa', 'Ser vencido o inferior', 'Capta el sentido de ser superado o hecho inferior, ya sea por fuerza externa o debilidad interna. El doble uso de Pedro en 2 Pedro 2 establece la palabra como descripción de atadura y esclavitud: «por aquello que una persona es vencida, a eso queda esclavizada». El uso irónico de Pablo en 2 Corintios añade el matiz de inferioridad comparativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68960, 'spa', 'Resonar o retumbar', 'Pablo emplea este vívido verbo en 1 Corintios 13:1 para describir el habla sin amor: se convierte en mero ruido como címbalo que retiñe o bronce que resuena. La forma participial enfatiza el carácter continuo del sonido. Los paralelos clásicos incluyen escudos de bronce resonando en batalla e insectos chirriando. Las traducciones al español (''resonando'') y al francés (''résonner'') captan bien la cualidad reverberante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68961, 'spa', 'Sonido o estruendo', 'Sonido, ruido o reporte reverberante que abarca fenómenos audibles desde rugidos naturales hasta estallidos sobrenaturales, y por extensión la ''fama'' o noticia que se propaga sobre alguien. En Pentecostés un sonido como de viento impetuoso llena toda la casa (Hch 2:2). Lucas 21:25 lo emplea para el bramido aterrador del mar en la convulsión escatológica. Hebreos 12:19 describe el espantoso toque de trompeta en el Sinaí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68963, 'spa', 'Mar, gran masa de agua', 'Cualquier gran extensión de agua, ya sea un mar con nombre propio como el mar de Galilea (Mt 4:18) o el mar Rojo (Heb 11:29), o bien el mar como entidad geográfica y cósmica. En Apocalipsis, el mar porta simbolismo escatológico como ámbito del caos que desaparecerá (Ap 21:1). La uniformidad de las traducciones en las principales lenguas confirma un núcleo semántico cohesivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68969, 'spa', 'Mujer en genealogía mesiánica', 'Mateo 1:3 nombra a Tamar como madre de Fares y Zara por medio de Judá, una de cuatro mujeres (además de María) mencionadas en la genealogía de Jesús. Su relato en Génesis revela su valentía al asegurar descendencia para la línea de su esposo fallecido cuando Judá incumplió el matrimonio levirático. El nombre hebreo que significa ''palmera'' sugiere belleza y fecundidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68970, 'spa', 'Asombro sobrecogedor', 'Quedar atónito o alarmado, con matices simultáneos de admiración y temor. Marcos emplea este verbo para retratar reacciones viscerales, casi involuntarias, ante la autoridad de Jesús. En Marcos 1:27 la multitud queda θαμβέω ante su poder sobre los espíritus inmundos; en Marcos 10:32 los discípulos están θαμβέω mientras él camina al frente hacia la cruz. El término capta un asombro que paraliza y estremece a la vez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68971, 'spa', 'Asombro ante lo divino', 'Enfatiza la cualidad visceral y abrumadora del asombro como respuesta a lo milagroso. El doble uso de Lucas lo vincula a las obras de poder de Jesús, tanto de palabra (autoridad sobre los demonios) como de hecho (provisión de peces). Hechos lo extiende al ministerio apostólico, mostrando el mismo poder sobrecogedor en acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68972, 'spa', 'Mortífero o letal', 'Marcos 16:18 promete que los creyentes beberán veneno mortal sin sufrir daño, una de varias señales milagrosas que acompañan a quienes creen. El adjetivo enfatiza sustancias genuinamente letales, no meramente peligrosas. Los paralelos clásicos incluyen reptiles venenosos, heridas mortales y sustancias que causan la muerte. Las traducciones multilingües (''mortal'', ''mortel'', ''toedlich'') subrayan consistentemente el carácter letal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68973, 'spa', 'Mortífero, letal', 'Santiago 3:8 emplea este vívido término para caracterizar la lengua humana como portadora de veneno mortal, resaltando su potencial destructivo. El adjetivo aparece en textos clásicos describiendo veneno de flechas, heridas fatales y juicios capitales. La estructura compuesta («portador de muerte») sugiere no una letalidad pasiva, sino un poder activo de causar muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68974, 'spa', 'muerte', 'La muerte como fin de la vida, abarcando la muerte natural (Heb 7:23), la ejecución violenta (Mt 10:21), la sentencia judicial (Mt 20:18; Mr 14:64) y la realidad teológica de la muerte espiritual como consecuencia del pecado (Ro 5:12; 6:23). Pablo y Juan personifican θάνατος como un poder enemigo que Cristo ha conquistado mediante la resurrección — «la muerte ha sido absorbida en victoria» (1 Co 15:54) — y que será finalmente destruido (Ap 20:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68980, 'spa', 'Dar muerte, matar, ejecutar (activa) — el sentido activo en el que agentes human', 'Dar muerte, matar, ejecutar (activa) — el sentido activo en el que agentes humanos causan deliberadamente la muerte de otra persona. Este sentido (7 apariciones) se concentra en los relatos sinópticos de la pasión y las advertencias escatológicas: el Sanedrín busca falso testimonio para ''darle muerte'' (Mt 26:59), el concilio matutino resuelve ''darle muerte'' (Mt 27:1), y Jesús profetiza la traición fraternal (Mt 10:21; Mc 13:12). Lucas emplea el verbo en la parábola de los labradores malvados (Lc 21:16) y en la persecución apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68982, 'spa', 'Ser muerto, padecer la muerte, ser mortificado (pasiva) — la voz pasiva en la qu', 'Ser muerto, padecer la muerte, ser mortificado (pasiva) — la voz pasiva en la que el sujeto es quien muere o experimenta una transformación semejante a la muerte. Este sentido (4 apariciones) porta fuerza tanto literal como metafórica: Cristo fue ''muerto en la carne pero vivificado en el espíritu'' (1 P 3:18), formando un par pasivo perfecto con ζῳοποιέω; Pablo cita el Salmo 44:22, ''por tu causa somos muertos todo el día'' (Ro 8:36), y declara que los creyentes ''fuisteis muertos a la ley mediante el cuerpo de Cristo'' (Ro 7:4), donde morir a la ley es una muerte metafórica que libera para una nueva vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68987, 'spa', 'Sepultar, enterrar a un difunto — realizar los ritos acostumbrados de colocar un', 'Sepultar, enterrar a un difunto — realizar los ritos acostumbrados de colocar un cuerpo en una tumba o sepulcro. Jesús emplea esta palabra en su impactante llamado al discipulado: ''deja que los muertos entierren a sus muertos'' (Mt 8:21-22; Lc 9:59-60), priorizando el reino sobre el deber judío primordial de la sepultura filial. Los discípulos de Juan el Bautista sepultan su cuerpo decapitado (Mt 14:12). En parábolas e historia: el rico fue sepultado (Lc 16:22), David murió y fue sepultado (Hch 2:29), Ananías y Safira fueron sacados y sepultados (Hch 5:6, 9-10), y en la fórmula credo paulina Cristo ''fue sepultado'' (1 Co 15:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68991, 'spa', 'Nombre propio patriarcal', 'Lucas 3:34 incluye a Taré en la genealogía ascendente, situado como padre de Abraham e hijo de Nacor. Génesis 11 narra su migración desde Ur y su muerte en Harán a los 205 años. El significado del nombre hebreo sigue siendo debatido entre los eruditos, con propuestas que van desde «demora» hasta vínculos lunares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68992, 'spa', 'Estar seguro', 'Ser osado o atrevido, especialmente en situaciones de confrontación — el aspecto combativo del valor dirigido contra los adversarios. Pablo advierte que se mostrará osado en persona contra quienes lo acusan (2 Co 10:1-2). El contexto desplaza el significado de la confianza tranquila hacia el coraje confrontativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68993, 'spa', 'Tener confianza', 'Estar confiado, poseer una seguridad interior asentada — una confianza firme y serena más que una audacia temeraria. Pablo confía en los corintios (2 Co 7:16); los creyentes mantienen su confianza incluso ante la muerte porque saben que estarán con el Señor (2 Co 5:6, 8); Hebreos 13:6 expresa una confianza resuelta en el socorro divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68996, 'spa', 'Ser osado', 'Mostrarse audaz o valiente de manera general, con disposición para actuar con determinación. Engloba el matiz más amplio de atreverse a hablar o actuar con firmeza, sin distinguir entre la confianza interior y la confrontación externa. Cubre usos donde el contexto no enfatiza ni la serenidad ni el enfrentamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68997, 'spa', 'Cobrar ánimo', 'Cobrar ánimo, tener buen ánimo — exhortación imperativa que insta a la calma confiada frente al miedo. En el NT cada aparición es palabra de aliento. Jesús la dirige al paralítico (Mt 9:2), a la mujer sanada (Mt 9:22) y a los discípulos aterrados sobre el mar (Mt 14:27; Mr 6:50).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69002, 'spa', 'Ánimo y valentía', 'Hechos 28:15 describe cómo Pablo cobró ánimo cuando los hermanos cristianos salieron a recibirlo camino a Roma, dando gracias a Dios por su presencia. El término enfatiza la valentía renovada y la confianza que brota de la comunión fraternal. Los paralelos clásicos lo asocian al coraje en batalla y la confianza ante los enemigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69004, 'spa', 'maravillarse, asombrarse — Sentir asombro o admiración ante algo extraordinario', 'maravillarse, asombrarse — Sentir asombro o admiración ante algo extraordinario: el sentido activo dominante que abarca casi todas las apariciones. Las multitudes se maravillan ante sanidades (Mt 9:33; 15:31), Pilato se asombra del silencio de Jesús (Mr 15:5), y el mismo Jesús se maravilla de la fe del centurión (Mt 8:10) y de la incredulidad de Nazaret (Mr 6:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69018, 'spa', 'ser admirado — Ser objeto de asombro o admiración en voz pasiva', 'ser admirado — Ser objeto de asombro o admiración en voz pasiva. La única aparición neotestamentaria es la visión paulina del Cristo que regresa, quien vendrá «para ser admirado entre todos los que creyeron» (2 Ts 1:10). Aquí el sujeto no se asombra sino que provoca asombro: un espectáculo teofánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69028, 'spa', 'admirar con parcialidad — Admirar en el sentido de mostrar parcialidad o adular ', 'admirar con parcialidad — Admirar en el sentido de mostrar parcialidad o adular a alguien por conveniencia, una extensión moralmente cargada. Judas describe a falsos maestros que «admiran personas» (θαυμάζοντες πρόσωπα) por afán de lucro (Jud 16), transformando el genuino asombro en adulación calculada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69029, 'spa', 'Maravilloso, admirable', 'En Mateo 21:15, los líderes religiosos se indignan al ver las cosas maravillosas que Jesús hacía —sanidades y milagros— y oír a los niños exclamando «¡Hosanna al Hijo de David!» en el templo. El término resalta la cualidad objetivamente prodigiosa de las obras de Jesús. Los paralelos clásicos describen acontecimientos extraordinarios que inspiran admiración y asombro reverente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69030, 'spa', 'Maravilloso, admirable', 'Maravilloso, admirable — describe los actos y obras de Dios que provocan reverente asombro. La piedra rechazada se convierte en piedra angular, «maravilloso ante nuestros ojos» (Mt 21:42; Mr 12:11). Los creyentes son llamados a la «luz admirable» de Dios (1 Pe 2:9). Apocalipsis 15:1, 3 lo emplea para las grandes obras de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69031, 'spa', 'Asombroso, sorprendente', 'Asombroso, sorprendente — expresa sorpresa o incredulidad ante un giro inesperado de los acontecimientos. El hombre nacido ciego declara que es «asombroso» que los fariseos no sepan de dónde viene Jesús a pesar del milagro (Jn 9:30). El énfasis recae en la perplejidad y el estupor más que en la reverencia devota.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69032, 'spa', 'Extraordinario', 'Extraordinario, fuera de lo común — uso general que abarca tanto la admiración reverente como la sorpresa, aplicado a aquello que trasciende lo ordinario y desafía las expectativas humanas. Funciona como término amplio que engloba el asombro ante lo divino y lo humanamente inexplicable sin distinguir entre reverencia y estupor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69033, 'spa', 'Diosa pagana', 'Hechos 19:27 registra al platero Demetrio advirtiendo que la predicación de Pablo pone en peligro la magnificencia de Artemisa y su templo, pues Pablo convence a la gente de que los dioses hechos con manos no son dioses. El término designa a Artemisa (Diana) de los efesios. Desde la perspectiva bíblica, tales deidades son ídolos falsos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69034, 'spa', 'Contemplación activa y atenta', 'Contemplación activa y atenta: mirar, observar o contemplar algo o a alguien con atención deliberada. Abarca usos indicativos, participiales, infinitivos e imperativos en 20 ocurrencias. Pasajes clave incluyen la pregunta de Jesús a las multitudes sobre Juan el Bautista (Mt 11:7; Lc 7:24), el rey inspeccionando a los invitados a la boda (Mt 22:11), Jesús viendo a Leví en el puesto de impuestos (Lc 5:27) y la declaración de 1 Juan 1:1 como testimonio ocular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69036, 'spa', 'Visibilidad pasiva', 'Visibilidad pasiva: ser visto, observado o puesto en exhibición ante otros. En Mt 6:1, Jesús advierte contra hacer justicia ''para ser vistos'' (θεαθῆναι) por la gente, y Mt 23:5 lo extiende a los fariseos que ensanchan sus filacterias ''para ser vistos.'' Mc 16:11 reporta que el Jesús resucitado ''fue visto'' (ἐθεάθη) por María Magdalena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69050, 'spa', 'Exhibición pública humillante', 'Hebreos 10:33 describe a creyentes que fueron convertidos en espectáculo mediante ultrajes y aflicciones públicas, soportándolo junto a otros que sufrían persecución similar. El participio pasivo enfatiza que fueron exhibidos contra su voluntad. La metáfora teatral capta la naturaleza pública y vergonzosa de su padecimiento: expuestos al escarnio y al maltrato como actores en un escenario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69051, 'spa', 'Lugar y espectáculo', 'Este sentido abarca tanto el recinto físico como el espectáculo metafórico. Las referencias a Éfeso son literales: un espacio de asamblea capaz de albergar hasta 25.000 espectadores, donde las reuniones cívicas podían convertirse en motines. El uso paulino en Corintios lleva el concepto al extremo metafórico: los apóstoles como el acto final de una exhibición pública de condenados a muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69052, 'spa', 'Azufre, piedra ardiente', 'Azufre, piedra de fuego — sustancia mineral combustible asociada al juicio divino por fuego. Jesús recuerda la lluvia de azufre sobre Sodoma (Lc 17:29). Apocalipsis lo despliega repetidamente: los caballos demoníacos exhalan fuego, humo y azufre (Ap 9:17-18), y el lago de fuego y azufre es destino final de los condenados (Ap 19:20; 20:10; 21:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69053, 'spa', 'Cualidad de deidad', 'Este sentido identifica la cualidad propia de la deidad, ya sea como esencia divina abstracta o como atributos divinos concretos. El discurso de Pablo en Atenas emplea el neutro sustantivado para conectar con el vocabulario filosófico, apuntando más allá de las representaciones materiales. En Pedro, el uso es explícitamente atributivo: poder divino y naturaleza divina son cualidades propias de Dios compartidas con los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69054, 'spa', 'Naturaleza divina', 'Romanos 1:20 afirma que el poder eterno y la naturaleza divina de Dios se perciben con claridad desde la creación, dejando a la humanidad sin excusa. El término enfatiza la cualidad de la divinidad discernible en lo creado. Se distingue de θεότης (Colosenses 2:9), enfocándose en los atributos divinos manifiestos en el orden creado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69055, 'spa', 'Sulfuroso, color azufre', 'Apocalipsis 9:17 describe corazas de color rojo fuego, azul oscuro y amarillo azufre, portadas por jinetes cuyos caballos exhalan fuego, humo y azufre. El adjetivo modifica las corazas, resaltando el color amarillo del azufre y vinculándolas visualmente con el fuego sulfuroso de los caballos. En el uso clásico describía aguas termales sulfurosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69056, 'spa', 'Voluntad, deseo, propósito', 'La voluntad, el deseo o el propósito firme de una persona o de Dios, designando lo que se quiere o se pretende realizar. Teológicamente dominante en el Padrenuestro (''hágase tu voluntad'', Mt 6:10), en el criterio de Jesús para el discipulado (''el que hace la voluntad de mi Padre'', Mt 7:21; 12:50), y en la doctrina paulina del propósito divino (Ef 1:5, 9, 11). El plural en ciertos pasajes apunta a los deseos carnales del ser humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69058, 'spa', 'Acto de voluntad soberana', 'Hebreos 2:4 describe cómo Dios confirmó el mensaje apostólico mediante señales, prodigios, milagros y distribuciones del Espíritu Santo conforme a su propia voluntad. El término enfatiza la elección soberana del Espíritu en la distribución de dones, no el mérito ni el deseo humano. En el uso filosófico clásico se exploraba la naturaleza del querer como distinta del objeto querido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69060, 'spa', 'querer, desear', 'El sentido volitivo básico: querer o desear algo. Es el uso más frecuente con diferencia, presente en todos los modos y tiempos. En Mt 16:24 («si alguno quiere venir en pos de mí») y Mt 15:32 («no quiero despedirlos en ayunas»), θέλω expresa un deseo directo. La amplitud de sujetos — Dios, Jesús, personas comunes — confirma su carácter universal como verbo volitivo primario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69066, 'spa', 'desear, anhelar', 'Desear o anhelar, frecuentemente con matiz optativo o contrafactual. En Mr 6:25, la hija de Herodías dice «quiero que me des la cabeza de Juan», y en Lc 1:62 los vecinos hacían señas preguntando cómo «deseaba» llamar al niño. El español «quisiera» capta la cualidad más suave y menos resuelta. Este sentido aparece cuando el resultado es incierto o se formula como un deseo más que como una decisión firme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69067, 'spa', 'estar dispuesto, consentir', 'Estar dispuesto o consentir, destacando la disposición más que el deseo activo. En Mt 23:37 Jesús lamenta: «¡Cuántas veces quise juntar a tus hijos... y no quisiste!», y en Mt 18:30 el siervo «no quiso» perdonar. El español capta bien esta distinción con el contraste entre «querer» (deseo activo) y «estar dispuesto» (disposición). Este sentido aparece cuando lo relevante es la voluntad de aceptar algo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69082, 'spa', 'determinar, proponerse', 'Querer con firmeza, proponerse o determinar, expresando intención decidida o decreto divino. En Hch 18:21 Pablo dice «volveré, si Dios quiere», y en 1 Co 4:19 declara «vendré pronto, si el Señor quiere». Cuando el sujeto es Dios (Mt 8:2-3, «si quieres, puedes limpiarme»), θέλω alcanza el registro de la voluntad soberana. El español distingue este matiz con expresiones como «Dios mediante» o «si Dios quiere».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69086, 'spa', 'deleitarse, complacerse', 'Complacerse o deleitarse en algo, donde el elemento volitivo se desliza hacia el afecto. En Ro 7:21 Pablo descubre que cuando «quiere» hacer el bien, el mal está presente — aquí θέλω se acerca más a «complacerse en». En Mt 2:18, Raquel «no quiso» ser consolada, expresando no solo rechazo sino disposición emocional. Este sentido, poco frecuente, marca la transición del querer al sentir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69115, 'spa', 'Cimiento, fundamento', 'Cimiento, fundamento: La base estructural sobre la cual se erige un edificio o muro, y por extensión cualquier fundamento sobre el cual algo se establece. El uso literal aparece en Lc 6:48-49 (el cimiento de una casa sobre roca) y Hch 16:26 (los cimientos de la prisión sacudidos). El uso figurado en Pablo identifica a Cristo como el único cimiento de la iglesia (1 Co 3:11) y a los apóstoles como piedras fundacionales (Ef 2:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69118, 'spa', 'Cimentar o fundar', 'Poner un fundamento o establecer firmemente, tanto en sentido de construcción física como de arraigo espiritual. En Matt 7:25 la casa edificada sobre la roca estaba bien fundada y resiste la tormenta; Heb 1:10 cita el Salmo 102 declarando que el Señor fundó la tierra. Los usos metafóricos son igualmente vívidos: Ef 3:17 ora para que los creyentes estén ''arraigados y cimentados'' en amor; Col 1:23 exhorta a permanecer ''fundados y firmes''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69119, 'spa', 'Instruido por Dios', 'En 1 Tesalonicenses 4:9, Pablo señala que los creyentes no necesitan instrucción sobre el amor fraternal porque son enseñados por Dios mismo. El adjetivo compuesto enfatiza la instrucción divina directa mediante el Espíritu, más allá de la enseñanza humana. Evoca Isaías 54:13 y el uso que Jesús hace de esa promesa en Juan 6:45.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69120, 'spa', 'Luchar contra Dios', 'Hechos 23:9 registra la advertencia de algunos fariseos de no oponerse a Pablo, para no hallarse luchando contra Dios. El modo subjuntivo sugiere una posibilidad real que intentan evitar. El verbo compuesto enfatiza la futilidad y el peligro de oponerse a los propósitos divinos. En el uso clásico, describía a mortales que batallaban contra los dioses en la mitología.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69121, 'spa', 'Opositor de Dios', 'En Hechos 5:39, Gamaliel aconseja sabiamente: si el movimiento de los apóstoles proviene de Dios, el Sanedrín no podrá destruirlo y solo conseguirá hallarse luchando contra Dios. El adjetivo compuesto aparece en forma sustantivada, describiendo en qué se convertirían. Los paralelos clásicos incluyen a los Gigantes guerreando contra el Olimpo. Las traducciones multilingües preservan el concepto de lucha contra Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69122, 'spa', 'Exhalado por Dios', 'En 2 Timoteo 3:16, Pablo declara que toda la Escritura es inspirada por Dios y útil para enseñar, reprender, corregir e instruir en justicia. El adjetivo compuesto enfatiza el origen divino: la Escritura procede del aliento mismo de Dios. Esto difiere de la mera inspiración (Dios soplando hacia adentro); es expiración (Dios soplando hacia afuera). Las traducciones multilingües muestran cómo los traductores han lidiado con este concepto singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69123, 'spa', 'el único Dios', 'El Dios supremo y único del monoteísmo judeocristiano; el Creador y Señor del universo; Yahvé revelado en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69127, 'spa', 'dios/deidad genérico', 'Cualquier dios o deidad del panteón pagano; dioses falsos o ídolos adorados en el mundo grecorromano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69137, 'spa', 'atributo divino/autoridad', 'Uso figurado o metafórico para personas o cosas que ejercen autoridad divina o poseen cualidades divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69138, 'spa', 'Piedad reverente', 'En 1 Timoteo 2:10, se instruye que las mujeres que profesan piedad deben adornarse con buenas obras en lugar de peinados elaborados y ropas costosas. El término enfatiza la piedad práctica y la reverencia hacia Dios expresada en la conducta diaria. Los paralelos clásicos muestran su significado de temor o adoración de los dioses. Las glosas multilingües («piedad», «Gottesfurcht») captan su cualidad devocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69139, 'spa', 'Temeroso de Dios', 'En Juan 9:31, el hombre sanado argumenta: «Sabemos que Dios no oye a los pecadores; pero si alguno es temeroso de Dios y hace su voluntad, a ese oye». El adjetivo enfatiza a quien teme y adora a Dios genuinamente. En el uso clásico denotaba a los religiosamente devotos. La evidencia multilingüe («temeroso-de-Dios», «gottesfuerchtig») preserva la cualidad de temor reverente y adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69140, 'spa', 'Aborrecedores de Dios', 'Romanos 1:30 incluye este término entre los vicios de la humanidad que suprime la verdad en injusticia. La mayoría de los intérpretes favorecen el sentido activo: quienes odian a Dios. Los paralelos clásicos enfatizan ser aborrecido por los dioses, pero el contexto paulino sugiere un odio activo hacia Dios, marcando la ruptura suprema entre Creador y criatura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69141, 'spa', 'Deidad esencial plena', 'Colosenses 2:9 declara que en Cristo habita corporalmente toda la plenitud de la Deidad, no solo atributos divinos sino la deidad misma en forma completa. Se diferencia de θειότης (naturaleza divina) al enfatizar la deidad absoluta y esencial. El término aparece en discusiones sobre la esencia divina en la filosofía griega y la teología cristiana primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69143, 'spa', 'Servicio y sanación', 'Este sentido abarca el servicio solícito, ya sea terapéutico, doméstico o escatológico. Lucas 9:11 describe a Jesús dando «sanación» a quienes necesitaban cura. Lucas 12:42 usa el genitivo del sustantivo para la servidumbre doméstica. La visión escatológica de Apocalipsis presenta hojas para la salud de las naciones: cuidado restaurador en la creación renovada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69144, 'spa', 'sanar, curar — Restaurar a alguien a la salud física curando enfermedad, lesión ', 'sanar, curar — Restaurar a alguien a la salud física curando enfermedad, lesión o dolencia. Domina el uso neotestamentario (42 de 43 apariciones), abarcando el ministerio sanador de Jesús (Mt 4:23-24; 8:7, 16; 9:35), la continuación apostólica del mismo y construcciones pasivas de personas que fueron sanadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69163, 'spa', 'servir, atender — Prestar servicio o atención, reflejando el significado griego ', 'servir, atender — Prestar servicio o atención, reflejando el significado griego clásico de cuidar a una deidad o un señor. Aparece solo en Hechos 17:25, donde Pablo declara que Dios no es θεραπεύεται —servido ni atendido— por manos humanas. Esta es una rara supervivencia del sentido pre-médico del término en el Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69164, 'spa', 'Siervo fiel honrado', 'Hebreos 3:5 contrasta a Moisés como siervo fiel en la casa de Dios con Cristo como Hijo sobre la casa. El término θεράπων resalta el papel honroso pero subordinado de Moisés. Los paralelos clásicos incluyen asistentes militares, compañeros devotos y adoradores de dioses. A diferencia de δοῦλος (esclavo), θεράπων porta mayor dignidad y sugiere un servicio voluntario y de confianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69165, 'spa', 'Cortar y recoger una cosecha del campo — el acto agrícola fundamental de segar g', 'Cortar y recoger una cosecha del campo — el acto agrícola fundamental de segar grano u otros productos. Usado literalmente del trabajo en el campo (Mt 6:26; Lc 12:24; Jn 4:36; Stg 5:4) y metafóricamente de recoger consecuencias espirituales, tanto positivas como negativas (Gá 6:7-9; 2 Co 9:6; Ap 14:15-16). En las parábolas de Jesús, el verbo subraya la rendición de cuentas: el amo cosecha donde no sembró.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69179, 'spa', 'Cosecha, siega', 'Cosecha, siega: la recolección de los cultivos, la temporada de cosecha o el fruto recogido, empleado tanto para el evento agrícola literal como para la rica imagen figurada de la recolección escatológica de Dios o del juicio final. Jesús envía obreros a la mies (Mt 9:37-38), la parábola de la cizaña identifica la siega como «el fin del siglo» (Mt 13:39), y Ap 14:15 presenta la tierra madura para ser segada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69183, 'spa', 'Calentarse al fuego', 'Calentarse junto al fuego — voz media/reflexiva que describe a alguien cerca de una hoguera para obtener calor físico. Las cuatro apariciones evangélicas retratan a Pedro calentándose junto al fuego de carbón durante el juicio de Jesús (Mr 14:54, 67; Jn 18:18, 25). La repetición intensifica la imagen de vulnerabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69184, 'spa', 'Recibir calor', 'Ser calentado, recibir calor corporal — el sentido pasivo que expresa la necesidad humana básica de abrigo. En Santiago 2:16 el mandato despectivo «calentaos y saciaos» deja al descubierto la hipocresía de ofrecer palabras en lugar de ropa y alimento a quien padece necesidad. El énfasis recae en la carencia física que queda sin satisfacer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69185, 'spa', 'Estar calentándose', 'Estar en proceso de calentarse — forma durativa que enfatiza la acción continuada de buscar calor. Se aplica al grupo que se calentaba junto al fuego en el patio (Jn 18:18, 25), subrayando la escena como un cuadro prolongado donde siervos y guardias permanecían cerca de las brasas durante la noche fría del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69186, 'spa', 'Calor físico intenso', 'Hechos 28:3 describe cómo una víbora, expulsada por el calor cuando Pablo colocó leña sobre el fuego, se le prendió de la mano. El término enfatiza la energía térmica que forzó a la serpiente a salir de su escondite. El uso médico clásico incluía calor febril e inflamación. El contexto prepara el milagro de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69187, 'spa', 'Estación estival', 'El sentido es directo: el verano como fenómeno natural observable. El contexto idéntico en los tres Sinópticos emplea el reverdecer y brotar de los árboles como señal segura de que el verano se acerca. Es sabiduría proverbial: los cambios estacionales son predecibles y reconocibles. El argumento de Jesús se basa en esa certeza: así como las señales botánicas anuncian el verano, las señales escatológicas anuncian la cercanía del reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69188, 'spa', 'Natural de Tesalónica', 'Persona originaria de Tesalónica, usado tanto para individuos (Aristarco en Hch 20:4; 27:2) como colectivamente para la comunidad cristiana de esa ciudad (1 Ts 1:1; 2 Ts 1:1). Como gentilicio propio se translitea de manera consistente en todas las lenguas en lugar de traducirse. El término sitúa a estos creyentes dentro de un importante centro urbano, comercial y político de la Macedonia romana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69189, 'spa', 'Ciudad de Tesalónica', 'La ciudad de Tesalónica en Macedonia, importante centro urbano sobre la Vía Egnatia y sitio de una de las plantaciones de iglesias más significativas de Pablo. En Hch 17:1 Pablo llega y predica en la sinagoga; Hch 17:11 contrasta Tesalónica con los bereanos más receptivos; Hch 17:13 registra a agitadores tesalonicenses persiguiendo a Pablo hasta Berea; Fil 4:16 recuerda la ayuda enviada por los filipenses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69190, 'spa', 'Revolucionario judío fallido', 'Hechos 5:36 registra que Gamaliel citó a Teudas como ejemplo de un pretendiente mesiánico fracasado que reunió a cuatrocientos hombres, fue ejecutado y vio dispersarse a sus seguidores. El nombre probablemente abrevia Teodoro. La identificación con el Teudas de Josefo genera dificultades cronológicas. Gamaliel argumenta que los movimientos meramente humanos se disuelven solos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69191, 'spa', 'Ver, percibir visualmente', 'Percepción visual básica: ver, contemplar o percibir algo con los propios ojos, frecuentemente como testigo directo de los acontecimientos. Las mujeres vinieron a ''ver'' el sepulcro (Mt 28:1), la gente ''vio'' al endemoniado sanado sentado en calma (Mc 5:15), y los espíritus inmundos ''veían'' a Jesús y caían ante él (Mc 3:11). Se trata de una visión que implica más que un vistazo fugaz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69193, 'spa', 'Observar, mirar con atención', 'Observación sostenida y atenta: contemplar, mirar o presenciar algo con concentración, a menudo como espectador de eventos significativos. Las mujeres ''observaban'' la crucifixión desde lejos (Mt 27:55; Mc 15:40, 47), Jesús ''observaba'' a la gente echando dinero en el arca (Mc 12:41), y declaró ''Yo veía a Satanás caer como un rayo'' (Lc 10:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69218, 'spa', 'Considerar, reflexionar', 'Una sola aparición en Heb 7:4 donde el verbo pasa de la vista física a la contemplación intelectual: ''Considerad (θεωρεῖτε) cuán grande era este hombre''. El autor de Hebreos invita a los lectores a ''contemplar'' la grandeza de Melquisedec no con los ojos, sino reflexionando sobre la evidencia de su estatura, transición del ámbito visual al cognitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69222, 'spa', 'Espectáculo público', 'Lucas 23:48 describe a las multitudes que acudieron a presenciar este espectáculo regresando a casa golpeándose el pecho tras la muerte de Jesús y las señales que la acompañaron. El término resalta la crucifixión como un evento público que atrajo observadores. En el uso clásico abarcaba la asistencia a festivales, juegos y representaciones teatrales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69223, 'spa', 'Vaina de espada', 'Juan 18:11 registra el mandato de Jesús a Pedro de poner su espada en la vaina, preguntando ''¿No he de beber la copa que el Padre me ha dado?'' El término denota directamente la funda de la espada. Los paralelos clásicos incluyen estuches para arcos y contenedores de armas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69224, 'spa', 'Amamantar o mamar', 'Dar de mamar o amamantar, dicho tanto de la madre que da leche como del lactante que la recibe. En Matt 21:16 Jesús cita el Salmo 8:2 sobre la alabanza ordenada por boca de los ''lactantes''; en Matt 24:19, Mark 13:17 y Luke 21:23 las advertencias escatológicas señalan a ''las que amamantan'' como especialmente vulnerables durante la huida; y en Luke 11:27 una mujer bendice los pechos que amamantaron a Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69225, 'spa', 'Sexo femenino', 'Femenino, perteneciente al sexo femenino. Se emplea en los relatos de la creación donde Dios hizo a la humanidad ''varón y hembra'' (Matt 19:4; Mark 10:6), en la declaración paulina de unidad en Cristo que trasciende las distinciones de género (Gal 3:28), y en la descripción de relaciones desordenadas en Romanos 1:26-27. La evidencia multilingüe lo traduce uniformemente con términos de sexo biológico básico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69226, 'spa', 'Trampa o lazo', 'Romanos 11:9 cita la imprecación de David pidiendo que su mesa se convierta en lazo y trampa, empleando la imagen de la caza. El término describe metafóricamente cómo lo que debería nutrir se convierte en medio de captura y juicio. Pablo aplica esto al tropiezo de Israel: su privilegio deviene instrumento de atrapamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69227, 'spa', 'Acechar para atrapar', 'Lucas 11:54 describe a los escribas y fariseos tendiendo emboscadas, intentando captar algo de la boca de Jesús para usarlo en su contra. El verbo emplea la imagen de la caza para sus intentos de atrapamiento verbal. Los paralelos clásicos incluyen cazar animales y perseguir cualquier presa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69228, 'spa', 'Combatir con fieras', 'La única aparición neotestamentaria se encuentra en la pregunta retórica de Pablo sobre luchar con fieras en Éfeso (1 Cor 15:32). El verbo θηριομαχέω significa literalmente combatir con animales salvajes (θηρίον + μάχομαι). Si Pablo habla de combate literal o usa metáfora para oposición intensa sigue en disputa, pero la imagen evoca una lucha violenta y mortal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69229, 'spa', 'bestia (apocalíptica) — La Bestia apocalíptica de Apocalipsis', 'bestia (apocalíptica) — La Bestia apocalíptica de Apocalipsis: una figura sobrenatural y maligna que simboliza la oposición a Dios y a su pueblo. Casi todas las apariciones neotestamentarias (39 de 46) pertenecen a este sentido, concentradas en Apocalipsis 11-20. Ap 13:1 presenta a la bestia que sube del mar; Ap 11:7, la bestia que asciende del abismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69230, 'spa', 'animal salvaje, fiera — Un animal salvaje o criatura peligrosa en sentido natura', 'animal salvaje, fiera — Un animal salvaje o criatura peligrosa en sentido natural y literal. Marcos 1:13 sitúa a Jesús entre las θηρία del desierto durante su tentación. Hechos 28:4-5 describe la criatura venenosa (probablemente una víbora) que se prendió de la mano de Pablo en Malta. Tito 1:12 cita al poeta cretense Epiménides llamando a los cretenses «malas bestias» (κακὰ θηρία).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69236, 'spa', 'Atesorar, acumular', 'Acumular, almacenar o guardar riquezas, recursos o consecuencias para uso futuro, ya sean provisiones literales o tesoros metafóricos. La enseñanza de Jesús en Mt 6:19-20 establece el contraste definitorio: no atesoréis tesoros en la tierra donde la polilla destruye, sino atesoradlos en el cielo. La extensión metafórica de Pablo en Ro 2:5 muestra el poder negativo del mismo verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69243, 'spa', 'Tesoro, riqueza acumulada', 'Tesoro, riqueza acumulada: Un tesoro o depósito de riqueza acumulada, usado tanto literalmente para bienes materiales como figuradamente para realidades espirituales. Los magos abren sus θησαυροί en la natividad (Mt 2:11). Jesús contrasta el tesoro en la tierra con el tesoro en el cielo (Mt 6:19-21) y describe el corazón como una tesorería de lo bueno o lo malo (Mt 12:35; Lc 6:45). Pablo ubica todos los tesoros de sabiduría en Cristo (Col 2:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69247, 'spa', 'Contacto físico prohibido', 'Este sentido se centra en el contacto físico, enmarcado consistentemente como prohibido o peligroso. Colosenses lo presenta como parte de regulaciones ascéticas que Pablo critica como mandamientos humanos. Hebreos lo emplea dos veces para un contacto que acarrea muerte: el toque del destructor (evitado por la sangre pascual) y cualquier contacto con la montaña santa del Sinaí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69248, 'spa', 'Padecer aflicción / ser atribulado (pasiva) — sufrir aflicción, tribulación o an', 'Padecer aflicción / ser atribulado (pasiva) — sufrir aflicción, tribulación o angustia, el sentido dominante del NT que aparece en formas pasivas y medias describiendo la experiencia de ser presionado por persecución, adversidad o angustia interior. Pablo escribe: ''en todo somos atribulados'' (2 Co 4:8), ''ningún reposo tuvo nuestro cuerpo, sino que en todo fuimos atribulados'' (2 Co 7:5), y expresa que la aflicción de unos no debe servir de alivio a otros (2 Co 8:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69251, 'spa', 'Afligir / causar angustia (activa) — afligir o causar tribulación activamente, c', 'Afligir / causar angustia (activa) — afligir o causar tribulación activamente, con un agente humano como sujeto que trae tribulación sobre otros. En 2 Tesalonicenses 1:6 Pablo declara que es ''justo delante de Dios pagar con tribulación a los que os atribulan'', usando el participio activo para identificar a los perseguidores como agentes directos de la opresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69255, 'spa', 'Apretar / agolparse (físico) — presionar o agolparse físicamente contra alguien,', 'Apretar / agolparse (físico) — presionar o agolparse físicamente contra alguien, como cuando una multitud aprieta con tal fuerza que el daño corporal se convierte en peligro real. En Marcos 3:9 Jesús pide a sus discípulos que tengan lista una barca ''a causa de la multitud, para que no le oprimieran'', donde la presión es compresión espacial literal y no tribulación emocional o espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69256, 'spa', 'Angosto / estrecho (metafórico) — usado como participio perfecto pasivo que func', 'Angosto / estrecho (metafórico) — usado como participio perfecto pasivo que funciona adjetivalmente para describir las dimensiones comprimidas de un camino. En Mateo 7:14 Jesús declara: ''Estrecha es la puerta y angosto el camino que lleva a la vida, y pocos son los que la hallan.'' El participio τεθλιμμένη evoca un camino apretado entre muros o acantilados, que solo permite el paso con dificultad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69257, 'spa', 'tribulación, aflicción — Presión, angustia o aflicción causada por circunstancia', 'tribulación, aflicción — Presión, angustia o aflicción causada por circunstancias externas como persecución, oposición social o catástrofe escatológica. La metáfora raíz es el aplastamiento o la presión física, extendida al sufrimiento psicológico y espiritual. Abarca las pruebas presentes que soportan los creyentes (Ro 5:3; 2 Co 1:4; 1 Ts 3:3), persecuciones específicas (Hch 11:19; 2 Ts 1:4) y la tribulación escatológica culminante (Mt 24:21; Ap 7:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69268, 'spa', 'Haber muerto, estar muerto', 'Estar en estado de muerte como resultado de haber muerto (aspecto perfectivo). Las nueve ocurrencias neotestamentarias emplean el tema de perfecto, enfatizando el hecho consumado de la muerte con su consecuencia perdurable. En los relatos de milagros --Lázaro (Jn 11:44), el hijo de la viuda (Lc 7:12), la hija de Jairo (Lc 8:49)-- el perfecto realza la magnitud del milagro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69275, 'spa', 'Mortal, perecedero', 'Sujeto a la muerte, mortal: describe el cuerpo humano como inherentemente perecedero y destinado a morir sin la intervención divina. En Rom 6:12 Pablo exhorta a los creyentes a no dejar que el pecado reine en su cuerpo mortal; en Rom 8:11 el Espíritu vivifica los cuerpos mortales; la declaración culminante de 1 Cor 15:53-54 proclama que ''esto mortal debe vestirse de inmortalidad''. En 2 Cor 4:11 la paradoja se agudiza: la vida de Jesús se manifiesta en nuestra carne mortal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69276, 'spa', 'Alborotar o turbar', 'Causar conmoción, provocar tumulto o estar interiormente turbado y agitado. Externamente, describe multitudes que generan alboroto: plañideras que lloran a gritos en la casa de Jairo (Matt 9:23; Mark 5:39), una turba que se amotina contra los compañeros de Pablo (Acts 17:5). Internamente, representa la perturbación ansiosa del ánimo, como en la dulce reprensión de Jesús a la inquietud de Marta (Luke 10:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69277, 'spa', 'Alboroto, motín', 'Alboroto, motín: perturbación pública que involucra a una multitud con amenaza de violencia o inestabilidad política. Se usa para la temida reacción popular ante el arresto de Jesús (Mt 26:5; Mc 14:2), el tumulto que presencia Pilato (Mt 27:24) y contextos posteriores a disturbios en Hechos (20:1; 21:34). Resalta el carácter ruidoso y desordenado de la situación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69279, 'spa', 'Tumulto, desorden', 'Tumulto: estado de confusión y agitación en un entorno público, sin implicar necesariamente un motín en toda regla. En Hch 24:18, Pablo insiste en que fue hallado en el templo sin ningún ''tumulto''. Capta un desorden más general, distinto de la perturbación a nivel de motín del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69280, 'spa', 'Conmoción, agitación', 'Conmoción, perturbación ruidosa de carácter doméstico o fúnebre, no político. En Mc 5:38, Jesús llega a la casa de Jairo y encuentra a personas haciendo gran alboroto con llanto y lamentación. El contexto es de duelo, no de hostilidad, pero el significado central sigue siendo el de agitación colectiva ruidosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69281, 'spa', 'Oprimir o quebrantar', 'En la cita de Isaías 61 que hace Lucas, el participio pasivo τεθραυσμένους describe a quienes necesitan liberación: los «quebrantados» u «oprimidos». El uso clásico muestra que θραύω pasó de la destrucción literal (romper alas, hacer pedazos rocas) al aplastamiento metafórico de la esperanza. La evidencia multilingüe oscila entre enfatizar la opresión y el quebranto interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69282, 'spa', 'Ganado doméstico', 'La pregunta de la mujer samaritana (Juan 4:12) evoca los rebaños de Jacob que abrevaban en el pozo ancestral, estableciendo continuidad con el relato patriarcal. El sustantivo θρέμμα designa animales domesticados de rebaño, particularmente ovejas y cabras que Jacob habría llevado al pozo. Las fuentes clásicas confirman este campo semántico: animales mansos, especialmente rumiantes, criados bajo cuidado humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69283, 'spa', 'Lamento vocal fúnebre', 'Realizar una lamentación vocal, plañir o entonar un canto fúnebre, generalmente en un contexto ritual o público. Aparece en la parábola de Jesús sobre los niños que gritan ''les cantamos endechas y no lamentasteis'' (Mt 11:17; Lc 7:32), resaltando la respuesta social esperada ante el duelo. En Lc 23:27 las mujeres θρηνέω camino al Gólgota, y en Jn 16:20 Jesús advierte a los discípulos que se lamentarán mientras el mundo se regocija.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69284, 'spa', 'Culto religioso externo', 'Adoración religiosa externa, práctica devocional o piedad visible como expresión de los compromisos de fe. En Hch 26:5 Pablo habla de la θρησκεία más estricta de los fariseos; en Col 2:18 aparece en la frase peyorativa ''culto a los ángeles,'' advirtiendo contra la devoción mal dirigida. Santiago 1:26-27 ofrece el contraste más agudo: la θρησκεία que no refrena la lengua es ''vana,'' mientras que la pura se manifiesta en cuidar a huérfanos y viudas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69285, 'spa', 'Religioso observante', 'Santiago emplea θρησκός retóricamente: si alguien se considera «religioso» pero no refrena su lengua, su religión es vana. El adjetivo destaca la observancia religiosa externa —culto regular, participación ritual— pero el contexto inmediato (v. 27) la contrasta con la «religión pura», definida por la acción ética: cuidar huérfanos y viudas, y mantenerse sin mancha del mundo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69287, 'spa', 'Cabello humano', 'Cabello humano: el sentido dominante que abarca trece de las quince apariciones en el NT. Se emplea en la enseñanza de Jesús sobre la providencia divina («ni un cabello de vuestra cabeza perecerá», Lc 21:18; «los cabellos de vuestra cabeza están todos contados», Mt 10:30), en actos narrativos de devoción (María secando los pies de Jesús, Lc 7:38, 44; Jn 11:2) y en la descripción apocalíptica (cabellos blancos como lana, Ap 1:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69290, 'spa', 'Pelo animal (pelo de camello)', 'Pelo animal (pelo de camello): pelo de animal, específicamente pelo de camello utilizado como material de vestimenta áspera. Aparece solo en las descripciones paralelas de Juan el Bautista vistiendo un manto de pelo de camello (Mt 3:4; Mr 1:6). En español se usa «pelo» en lugar de «cabello» aquí, una distinción léxica natural entre el pelaje animal y el cabello humano que valida interlingüísticamente la frontera entre ambos sentidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69292, 'spa', 'Alarma y perturbación', 'Este sentido enfatiza la perturbación emocional y la alarma provocada por el miedo, especialmente en contextos apocalípticos. Jesús advierte que guerras y trastornos «no son aún el fin», y Pablo aborda la ansiedad escatológica causada por falsas enseñanzas. Se trata de una agitación interior que los creyentes deben resistir con fe y calma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69293, 'spa', 'Gotas densas o coágulos', 'El relato lucano de la pasión describe el sudor de Jesús volviéndose «como grandes gotas de sangre que caían a tierra» (22:44). El sustantivo θρόμβοι enfatiza el tamaño y peso de las gotas: no transpiración fina, sino gotas densas semejantes a coágulos. Los escritores médicos usaban θρόμβος para coágulos sanguíneos; la imagen lucana evoca grumos sustanciales en su caída.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69294, 'spa', 'Trono, sede de autoridad', 'Trono o asiento de autoridad real y divina, que designa tanto el objeto físico como la soberanía que simboliza. Jesús invoca el trono de Dios como sede suprema de juicio (''el cielo es el trono de Dios'', Mt 5:34), promete tronos a los Doce (Mt 19:28) y recibe el trono de David como cumplimiento mesiánico (Lc 1:32). El término alcanza su mayor densidad en las visiones de la sala del trono de Apocalipsis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69296, 'spa', 'Ciudad de Tiatira', 'Nombre propio de una ciudad de Lidia (actual Turquía occidental), mencionada como lugar de origen de Lidia, la comerciante de púrpura (Hch 16:14), y como una de las siete iglesias del Apocalipsis (Ap 1:11; 2:18, 24). Su importancia económica — especialmente sus talleres de tinte y gremios comerciales — constituye el trasfondo tanto del relato de Lidia como de la preocupación de la carta del Apocalipsis con el compromiso económico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69297, 'spa', 'Hija en el sentido primario', 'Hija en el sentido primario: una mujer en relación con su padre o madre, o a quien se dirige con afecto familiar. El uso dominante en 22 ocurrencias incluye hijas literales (la hija de Herodías, Mt 14:6; la hija de Jairo, Mt 9:18), el tierno llamado de Jesús ''Hija, tu fe te ha sanado'' (Mt 9:22) y declaraciones relacionales como ''hija contra madre'' (Mt 10:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69298, 'spa', 'Hijas en plural, designando un grupo de descendientes femeninas o miembros de un', 'Hijas en plural, designando un grupo de descendientes femeninas o miembros de una comunidad. Las cinco ocurrencias incluyen ''hijas de Aarón'' para el linaje sacerdotal (Lc 1:5), ''hijas de Jerusalén'' como apelación comunitaria (Lc 23:28) y la profecía de Pentecostés de que ''vuestras hijas profetizarán'' (Hch 2:17). El plural extiende el lenguaje de parentesco de la familia al pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69300, 'spa', 'La construcción genitiva ''de hija,'' que aparece una vez en Hebreos 11', 'La construcción genitiva ''de hija,'' que aparece una vez en Hebreos 11:24, donde Moisés rehúsa ser llamado ''hijo de la hija del Faraón'' (θυγατρὸς Φαραώ). Esta única ocurrencia preserva el vínculo familiar mientras lo enmarca en una narrativa de renuncia y elección de identidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69304, 'spa', 'Tempestad violenta', 'Hebreos 12:18 enumera θύελλα entre los fenómenos aterradores del Sinaí —tiniebla, oscuridad, tempestad— que hacían temible el acercamiento a Dios bajo el antiguo pacto. Denota tormentas violentas, huracanes o torbellinos que marineros y viajeros temían. Las fuentes clásicas lo emplean para tormentas marítimas destructivas e imágenes bélicas. Simboliza la majestad inaccesible de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69305, 'spa', 'Madera aromática de lujo', 'En el catálogo de mercancías lujosas de Apocalipsis, θύϊνον ξύλον designa la madera del árbol θύον, apreciada en la antigüedad por sus propiedades aromáticas y su veta exquisita. Los escritores antiguos la describen como sumamente costosa, usada en mobiliario elaborado y revestimientos decorativos. El adjetivo θύϊνος la señala como artículo de prestigio en la economía mercantil de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69306, 'spa', 'Incienso, ofrenda aromática', 'Incienso, sustancia aromática quemada como ofrenda sagrada en el culto, cuyo humo ascendente simboliza las oraciones que suben a Dios. En Lc 1:10-11, el deber sacerdotal de Zacarías de quemar incienso en el altar del Templo prepara el escenario para el anuncio angélico. En Apocalipsis, el incienso alcanza una significación cósmico-litúrgica: las copas de oro de incienso son las oraciones de los santos (Ap 5:8), y un ángel mezcla incienso con oraciones ante el trono celestial (Ap 8:3-4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69309, 'spa', 'Incensario o altar', 'Hebreos 9:4 ubica el θυμιατήριον entre los enseres del Lugar Santísimo. El término puede significar un incensario portátil o el altar del incienso propiamente dicho, lo que genera tensión interpretativa: el altar del incienso se situaba normalmente fuera del velo, pero Hebreos parece ubicarlo dentro. En la LXX, θυμιατήριον se aplica tanto a incensarios como al altar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69310, 'spa', 'Ofrecer incienso ritual', 'Lucas comienza con Zacarías elegido por sorteo para θυμιᾶσαι, quemar incienso en el santuario (1:9). Este verbo designa la acción ritual de ofrecer incienso, un deber sacerdotal que se rotaba entre muchos sacerdotes, convirtiéndolo en un honor potencialmente único en la vida. El incienso simbolizaba las oraciones de Israel ascendiendo a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69311, 'spa', 'Hostilidad furiosa', 'Hechos describe a Herodes Agripa I como θυμομαχῶν contra Tiro y Sidón (12:20), literalmente «peleando con ira». La delegación de esas ciudades busca la paz, sugiriendo un embargo o presión política derivada de la cólera real. El compuesto θυμομαχέω intensifica más allá de la simple ira, llegando a la contienda airada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69312, 'spa', 'Ira, furor, rabia', 'Ira, furor, rabia: Enojo intenso y apasionado, usado tanto para la rabia humana repentina como para la ira escatológica de Dios. Apocalipsis domina el uso, empleando θυμός como término casi técnico para el juicio divino: ''el vino del furor de la ira de Dios'' se derrama desde copas de oro sobre la tierra (Ap 14:8, 10, 19; 15:1, 7; 16:1, 19; 18:3; 19:15). Para la rabia humana, Lc 4:28 capta la furia explosiva de la multitud en Nazaret.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69318, 'spa', 'Enfurecerse, airarse', 'Mateo emplea el aoristo pasivo ἐθυμώθη para la reacción de Herodes al ser engañado por los magos (2:16). El verbo θυμόω en voz media/pasiva significa «enfurecerse, llenarse de ira». La furia de Herodes lo impulsa a ordenar la matanza de los varones menores de dos años en Belén, cólera asesina que enmascara su inseguridad política.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69319, 'spa', 'una puerta — El sentido nuclear singular', 'una puerta — El sentido nuclear singular: una puerta, portón o entrada específica a un edificio o espacio cerrado. Jesús enseña a orar tras una puerta cerrada (Mt 6:6), el novio cierra la puerta (Mt 25:10), y José hace rodar una piedra contra la puerta del sepulcro (Mt 27:60). La multitud agolpándose «a la puerta» (Mr 1:33; 2:2) establece este sentido concreto y arquitectónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69320, 'spa', 'puertas (definidas) — Puertas en plural en un entorno reconocible o definido, a ', 'puertas (definidas) — Puertas en plural en un entorno reconocible o definido, a menudo con peso figurativo o escatológico. Jesús de pie «a las puertas» señala llegada inminente (Mt 24:33; Mr 13:29), y las puertas están cerradas donde los discípulos se esconden por temor (Jn 20:19, 26). El artículo definido marca estas como barreras conocidas y esperadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69321, 'spa', 'puertas (intervención divina) — Puertas en plural como objeto de intervención di', 'puertas (intervención divina) — Puertas en plural como objeto de intervención divina: abiertas, sacudidas o cerradas por fuerza sobrenatural. Un ángel abre las puertas de la prisión de noche (Hch 5:19), un terremoto las abre de golpe (Hch 16:26-27), y las puertas del templo se cierran tras una turba (Hch 21:30). El patrón es distintivamente lucano y destaca las puertas como instrumentos en narrativas de rescate divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69324, 'spa', 'Escudo grande oblongo', 'Efesios 6:16 emplea θυρεός para el «escudo de la fe» que apaga dardos encendidos. Designa el escudo grande oblongo (distinto del redondo ἀσπίς), con forma de puerta (θύρα) y cobertura casi total del cuerpo. Los legionarios romanos usaban el scutum de esta manera; la elección de θυρεός subraya protección completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69326, 'spa', 'Portero o guardián', 'Persona apostada en una puerta o portón para regular el acceso, funcionando como guardia y vigilante. En Jn 10:3 el θυρωρός abre la puerta del redil al verdadero pastor, simbolizando la autoridad espiritual legítima. En Jn 18:16-17 una portera en la residencia del sumo sacerdote admite a Pedro y luego lo confronta por su asociación con Jesús. Mr 13:34 sitúa al portero en un contexto escatológico de vigilancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69327, 'spa', 'Un sacrificio u ofrenda presentada a Dios, que abarca el acto físico de la inmol', 'Un sacrificio u ofrenda presentada a Dios, que abarca el acto físico de la inmolación, la víctima misma y metafóricamente la adoración espiritual. Jesús cita dos veces Oseas 6:6 — ''Misericordia quiero y no sacrificio'' (Mt 9:13; 12:7) — redefiniendo el concepto. Marcos 12:33 contrasta la devoción interior con los holocaustos, mientras que Hebreos desarrolla cómo el único sacrificio de Cristo supera todo el sistema levítico (Heb 9:26; 10:1-12). Pablo exhorta a ofrecer los cuerpos como ''sacrificio vivo'' (Ro 12:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69332, 'spa', 'Estructura elevada para presentar sacrificios, incienso u ofrendas a Dios — abar', 'Estructura elevada para presentar sacrificios, incienso u ofrendas a Dios — abarcando el altar del templo de Jerusalén (Mt 5:23-24), el altar del incienso (Lc 1:11; Ap 8:3) y el altar celestial en Apocalipsis (Ap 6:9; 9:13). Jesús lo referencia al enseñar sobre la reconciliación antes de la adoración y para exponer la casuística farisaica sobre los juramentos (Mt 23:18-20). Pablo lo invoca para fundamentar el derecho de los ministros del evangelio al sustento material (1 Co 9:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69334, 'spa', 'Ofrecer sacrificio ritual', 'Ofrecer sacrificio ritual: designa el acto cultual de presentar un animal como ofrenda religiosa, ya sea al Dios de Israel o a deidades paganas. En Hch 14:13 el sacerdote de Zeus quería ofrecer sacrificio, y en Mr 14:12 / Lc 22:7 se refiere al cordero pascual sacrificado ritualmente. Las glosas multilingües favorecen consistentemente el vocabulario sagrado aquí: francés sacrifier, alemán opfern, español sacrificar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69337, 'spa', 'Matar o degollar', 'Matar o degollar: describe el acto físico de degollar o matar un animal (o figuradamente a una persona) sin énfasis primario en lo ritual. En Lc 15:23 el padre ordena matar el becerro gordo para la fiesta de celebración, y en Jn 10:10 lleva el sentido violento de destruir la vida. El español distingue claramente este sentido del primero al cambiar de «sacrificar» a «matar».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69345, 'spa', 'Tomás (apóstol) — uno de los doce discípulos de Jesús, también llamado Dídimo (''', 'Tomás (apóstol) — uno de los doce discípulos de Jesús, también llamado Dídimo (''Gemelo''). Figura en cada catálogo apostólico (Mt 10:3; Mc 3:18; Lc 6:15; Hch 1:13). El Evangelio de Juan lo presenta con especial relieve: su valiente declaración ante la tumba de Lázaro (Jn 11:16), su sincera pregunta en la Última Cena sobre no conocer el camino (Jn 14:5), su negativa inicial a creer en la resurrección sin ver las marcas de los clavos (Jn 20:25), y su confesión de fe suprema ''¡Señor mío y Dios mío!'' al encontrarse con el Cristo resucitado (Jn 20:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69348, 'spa', 'Coraza o peto', 'Coraza o peto: armadura defensiva que se lleva sobre el pecho. Pablo la usa figuradamente para la protección espiritual: la «coraza de justicia» (Eph 6:14) y la «coraza de fe y amor» (1 Thess 5:8), aludiendo a Isaiah 59:17. En Apocalipsis aparece literalmente en las visiones de ejércitos sobrenaturales: las criaturas con corazas como de hierro (Rev 9:9) y la caballería del Éufrates con corazas de colores brillantes (Rev 9:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69350, 'spa', 'El patriarca Jacob/Israel, nieto de Abraham y padre de las doce tribus, invocado', 'El patriarca Jacob/Israel, nieto de Abraham y padre de las doce tribus, invocado a lo largo del NT como el tercer pilar de la tríada ancestral (Mt 8:11; 22:32; Hch 3:13; 7:32). También referenciado en Jn 4:5-12 como el antepasado que dio el pozo en Sicar, en el recuento histórico de Esteban sobre los orígenes de Israel (Hch 7:8-15, 46) y en el argumento de Pablo sobre la elección citando a Malaquías: ''A Jacob amé, mas a Esaú aborrecí'' (Ro 9:13). Un segundo Jacob aparece en la genealogía de Mateo como padre de José (Mt 1:15-16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69352, 'spa', 'Jacobo (Iakobos) — El nombre propio Ἰάκωβος (Jacobo/Santiago), llevado por vario', 'Jacobo (Iakobos) — El nombre propio Ἰάκωβος (Jacobo/Santiago), llevado por varios individuos neotestamentarios. Su origen hebreo (Ya''aqov) lo vincula con el patriarca, pero la forma griega distingue a los portadores del NT. Las referencias abarcan los relatos de llamamiento (Mt 4:21), el concilio de Jerusalén (Gá 2:9) y el saludo de la epístola (Stg 1:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69359, 'spa', 'Don de sanidad', 'Este sentido se refiere a la sanidad como don espiritual o carisma dentro de la iglesia. La forma plural constante y la construcción genitiva («dones de sanidades») sugieren diversidad en cómo se manifiesta la curación. Las preguntas retóricas de Pablo establecen que no todos reciben este don, al igual que no todos son apóstoles ni profetas: los dones son distribuidos según la voluntad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69360, 'spa', 'Mago opositor de Moisés', 'Pablo invoca a Jambres (con Janes) como opositores históricos a la verdad divina (2 Tim 3:8). La tradición judía los identificó como los magos del faraón que imitaron las señales de Moisés mediante brujería. El apóstol los usa tipológicamente: así como resistieron a Moisés, falsos maestros resisten la verdad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69361, 'spa', 'Antepasado de Jesús', 'La genealogía de Lucas incluye a Ἰανναί (3:24) en la sección posexílica, situado entre Melqui y José (hijo de Matatías). No aparece en ningún otro pasaje bíblico ni se conserva información biográfica. Lucas traza la línea de Jesús a través de antepasados poco conocidos del período posdavídico con función teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69362, 'spa', 'Mago opositor de Moisés', 'En 2 Timoteo 3:8, Pablo cita a Ἰάννης καὶ Ἰαμβρῆς como quienes «resisten la verdad»: magos del faraón que se opusieron a Moisés. Éxodo 7-8 describe hechiceros que duplicaron señales de Moisés (vara en serpiente, agua en sangre) antes de fracasar. La tradición judía preservó estos nombres en targumes y otras fuentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69363, 'spa', 'Restaurar a alguien a la salud curando una enfermedad o dolencia física, usado p', 'Restaurar a alguien a la salud curando una enfermedad o dolencia física, usado predominantemente de las sanidades milagrosas de Jesús y su extensión apostólica. El siervo del centurión sanado con una palabra (Mt 8:8, 13), la mujer con flujo de sangre sanada al instante (Mc 5:29; Lc 8:47) y las multitudes que venían para ser sanadas (Lc 6:18-19; 9:2, 11) ejemplifican el sentido literal. Metafóricamente, describe la restauración espiritual: Mateo y Juan citan Isaías 6:10 — ''no sea que se conviertan y yo los sane'' (Mt 13:15; Jn 12:40) — y 1 Pedro 2:24 aplica Isaías 53:5: ''por sus heridas fuisteis sanados.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69381, 'spa', 'Patriarca antediluviano', 'Lucas 3:37 incluye a Ἰάρετ entre los antepasados antediluvianos de Jesús, correspondiente al Jared de Génesis 5:15-20, padre de Enoc e hijo de Mahalalel. Vivió 962 años según la cronología del Génesis. Al trazar el linaje hasta Adán, Lucas establece la solidaridad de Jesús con toda la humanidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69382, 'spa', 'Acto de curación', 'Este sentido abarca la sanidad como acto o proceso concreto. Lucas lo presenta como parte de la misión mesiánica de Jesús junto con el exorcismo, demostrando la llegada del reino. Hechos lo emplea tanto como hecho consumado (la señal realizada en el cojo) como petición continua (los discípulos pidiendo a Dios que siga sanando mediante su poder).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69383, 'spa', 'Piedra preciosa jaspe', 'Piedra preciosa o semipreciosa, probablemente un cuarzo opaco, utilizada en Apocalipsis como símbolo principal de la luminosidad divina. En Ap 4:3 la apariencia del Dios entronizado se compara con jaspe y sardio; en Ap 21:11 la ciudad santa resplandece con la gloria de Dios como jaspe ''diáfano como el cristal''; el muro de la ciudad es de jaspe puro (Ap 21:18) y el jaspe es la primera piedra de los cimientos (Ap 21:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69384, 'spa', 'Jasón, nombre propio', 'Jasón, nombre propio que designa a un cristiano de Tesalónica que hospedó a Pablo y Silas y fue llevado ante las autoridades de la ciudad por una turba hostil (Acts 17:5-9). Podría ser la misma persona mencionada como pariente de Pablo en Rom 16:21. El nombre es una forma helenizada usada comúnmente por judíos de habla griega.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69385, 'spa', 'Médico, doctor', 'Médico, sanador profesional que diagnostica y trata enfermedades. El término tiene peso tanto literal como proverbial en el NT. En sentido literal describe a los doctores que la mujer con hemorragia consultó infructuosamente (Mc 5:26), y al compañero de Pablo, Lucas (Col 4:14). En sentido proverbial, Jesús lo emplea en dos dichos memorables: los sanos no necesitan médico (Mt 9:12; Mc 2:17; Lc 5:31), y la provocación de Nazaret ''Médico, cúrate a ti mismo'' (Lc 4:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69390, 'spa', 'Apariencia visible', 'En el relato de la resurrección según Mateo, la ἰδέα del ángel se describe «como un relámpago» (28:3), refiriéndose a su aspecto exterior visible. El sustantivo enfatiza lo que los guardias y las mujeres percibieron con sus ojos. En el griego clásico abarca desde la forma física hasta las «Ideas» platónicas, pero aquí significa sencillamente apariencia concreta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69391, 'spa', 'propio, de uno mismo', 'El adjetivo posesivo estándar que significa «propio, de uno mismo», usado atributiva o predicativamente con diversos sustantivos. Jesús regresa a «su propia ciudad» (Mt 9:1), el señor confía a los siervos «sus propios bienes» (Mt 25:14-15), y Pablo habla de «su propio cuerpo» y «su propio marido/esposa» (1 Co 7:2-4). Español propio/propia cubre este sentido posesivo central de forma natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69392, 'spa', 'en privado, aparte', 'El giro adverbial κατ᾽ ἰδίαν, que significa «en privado, aparte, a solas». Describe característicamente a Jesús retirándose con los Doce lejos de las multitudes (Mt 14:13; 17:1; 20:17) o explicando parábolas en privado (Mr 4:34). El español «aparte» o «a solas» lo traduce con naturalidad. Su uso constante en todas las lenguas confirma que funciona como expresión adverbial fija.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69397, 'spa', 'los suyos, los de su casa', 'La forma sustantivada οἱ ἴδιοι («los suyos») o τὰ ἴδια («lo suyo, su hogar»). Jn 1:11 formula el punto teológico con devastadora concisión: «A lo suyo vino, y los suyos no le recibieron». Jn 13:1 dice que Jesús amó «a los suyos que estaban en el mundo», y Hch 4:23 registra a los apóstoles volviendo «a los suyos». Este sentido relacional va más allá de la mera posesión hacia el vínculo comunitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69401, 'spa', 'individualmente, en particular', 'El sentido distributivo «individualmente, en particular, a cada uno por separado». En 1 Co 12:11, el Espíritu reparte dones «a cada uno en particular» (ἰδίᾳ). El español «particularmente» o «individualmente» lo expresa con exactitud. Es infrecuente en el NT, pero representa un uso genuino del griego clásico que marca la distribución específica frente a la acción colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69410, 'spa', 'Persona sin formación', 'Persona sin formación o sin destreza profesional, un lego que carece de pericia profesional o pulimento retórico. Aplicado a Pedro y Juan, a quienes el Sanedrín veía como «hombres sin letras e indoctos» (Acts 4:13), y usado por Pablo tanto para los ajenos al culto que no pueden seguir la glosolalia (1 Cor 14:16, 23-24) como de manera autodespreciativa respecto a su propia capacidad oratoria (2 Cor 11:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69411, 'spa', 'Región de Idumea', 'Marcos 3:8 enumera Ἰδουμαία entre las regiones de donde las multitudes acudían a Jesús: el nombre helenizado de Edom, al sur de Judea. Históricamente fue tierra de los descendientes de Esaú. Tras la conquista babilónica, los edomitas migraron al norte formando Idumea. En época de Jesús era una región reconocida, cuna de los antepasados herodianos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69412, 'spa', 'Sudor corporal', 'El relato de la pasión según Lucas narra que el ἱδρώς de Jesús se hizo «como grandes gotas de sangre» (22:44) durante su oración en Getsemaní. El sustantivo significa sudor o transpiración, pero el contexto y la comparación con sangre subrayan la intensidad de su agonía. Las fuentes clásicas asocian ἱδρώς con el esfuerzo extremo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69413, 'spa', 'Jezabel simbólica', 'La carta a Tiatira en Apocalipsis condena tolerar a «Jezabel» (2:20), nombre simbólico para una falsa profetisa que promueve el sincretismo: comer alimentos ofrecidos a ídolos e inmoralidad sexual. La Ἰεζάβελ histórica (1 Reyes 16:31ss) fue la reina fenicia de Acab que introdujo el culto a Baal y mató profetas. Su nombre personifica la seducción idolátrica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69416, 'spa', 'Servicio sacerdotal', 'El relato de Lucas comienza con Zacarías ἱερατεύειν, es decir, ejerciendo como sacerdote (1:8) cuando su división estaba de turno. El verbo denota el cumplimiento de las funciones oficiales del sacerdocio: ofrecer sacrificios, quemar incienso y pronunciar bendiciones. Su selección por sorteo para entrar al santuario y quemar incienso fue el contexto del anuncio de Gabriel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69417, 'spa', 'El profeta Jeremías', 'Este sentido identifica al profeta mayor autor del libro bíblico que lleva su nombre. La referencia de Mateo 16 muestra que Jeremías era una categoría posible para entender a Jesús: un profeta sufriente que llama a Israel al arrepentimiento. Las citas de cumplimiento conectan la historia de Jesús con patrones proféticos, aunque la atribución de Mateo 27 a Jeremías en lugar de Zacarías sigue siendo un problema textual discutido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69418, 'spa', 'sacerdote — Un oficiante del culto que realiza ritos sagrados y ofrece sacrifici', 'sacerdote — Un oficiante del culto que realiza ritos sagrados y ofrece sacrificios. En los Evangelios se refiere a sacerdotes del templo judío que certifican sanidades (Mt 8:4; Lc 17:14); la parábola del buen samaritano nombra a un sacerdote que pasa de largo (Lc 10:31). Zacarías sirve como sacerdote de la división de Abías (Lc 1:5). Hebreos redefine el oficio cristológicamente: Jesús es sacerdote para siempre según el orden de Melquisedec (He 5:6; 7:11-21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69422, 'spa', 'Jericó (ciudad)', 'Jericó, la histórica ciudad amurallada cerca del río Jordán y el mar Muerto, situada a unos 250 metros bajo el nivel del mar. Las siete apariciones en el NT se agrupan en torno a dos temas: el ministerio de Jesús en el camino a Jerusalén y el capítulo de la fe en Hebreos. Los Evangelios sinópticos sitúan en Jericó la sanación de ciegos (Mt 20:29; Mc 10:46; Lc 18:35) y la conversión de Zaqueo (Lc 19:1), mientras que la parábola del buen samaritano transcurre en su camino (Lc 10:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69424, 'spa', 'Templo, recinto sagrado', 'El complejo del templo o recinto sagrado, referido a todo el conjunto de edificaciones del templo de Jerusalén, incluyendo sus atrios, pórticos y estructuras circundantes, a diferencia de ναός, que designa el santuario interior propiamente dicho. Jesús enseña en el ἱερόν (Mt 21:23; Lc 19:47; Jn 7:14), expulsa a los mercaderes de sus atrios (Mt 21:12; Mc 11:15) y es tentado en su pináculo (Mt 4:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69426, 'spa', 'Reverente y decoroso', 'Pablo instruye a las mujeres mayores a ser ἱεροπρεπεῖς en su conducta (Titus 2:3) — reverentes, dignas, como corresponde a quienes sirven en lo santo. El adjetivo significa "apropiado para lo sagrado" (ἱερός + πρέπω), enfatizando un comportamiento que refleja la seriedad de la responsabilidad espiritual. Su conducta debe estar a la altura de su vocación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69427, 'spa', 'Sagrado, consagrado', 'Lo que pertenece o está asociado a lo divino, consagrado, sagrado. Se usa sustantivadamente para el servicio del templo en 1 Co 9:13, donde ''los que realizan las cosas sagradas'' (τὰ ἱερὰ ἐργαζόμενοι) comen del templo. En 2 Ti 3:15 modifica a γράμματα para referirse a las ''sagradas escrituras'' que Timoteo conoció desde niño. El final largo de Marcos (16:20) habla del ''mensaje sagrado e imperecedero'' de la salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69428, 'spa', 'Jerusalén (forma helenizada)', 'Nombre griego helenizado de Jerusalén, capital de Judea y epicentro del culto de Israel, usado en los Evangelios y Hechos para la ciudad terrenal donde Jesús enseñó, padeció, murió y resucitó (Mt 2:1; 3:5; 20:17-18). La forma Ἱεροσόλυμα (neutro plural, declinable) es favorecida por los evangelistas y contrasta con la indeclinable Ἰερουσαλήμ preferida por Pablo y Apocalipsis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69430, 'spa', 'Saquear templos', 'Pablo confronta la hipocresía judía: σὺ ὁ βδελυσσόμενος τὰ εἴδωλα ἱεροσυλεῖς; (Rom 2:22) — "Tú que abominas los ídolos, ¿cometes sacrilegio?" El verbo ἱεροσυλέω significa saquear templos, robar objetos sagrados — un acto criminal y sacrílego. La acusación apunta a judíos que lucraban con templos paganos o violaban la santidad del templo por avaricia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69431, 'spa', 'Sacrílego saqueador', 'El secretario de Éfeso declara que los compañeros de Pablo no son ἱεροσύλους — ni saqueadores de templos (Acts 19:37). El sustantivo describe a quienes saquean templos o roban propiedad sagrada, combinando criminalidad con impiedad. El funcionario distingue entre la predicación de Pablo y el sacrilegio directo, protegiéndolo legalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69432, 'spa', 'Ministrar sacerdotalmente', 'Pablo emplea ἱερουργοῦντα metafóricamente para describir su ministerio apostólico (Rom 15:16): sirve el evangelio "de manera sacerdotal," haciendo de los gentiles una ofrenda aceptable a Dios. El verbo denota la realización de ritos sagrados o servicio sacerdotal, aplicado aquí a la evangelización. Pablo reimagina la labor misionera como servicio cúltico: él es el sacerdote, su ofrenda son los gentiles convertidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69433, 'spa', 'Jerusalén', 'Nombre propio de Jerusalén, la ciudad santa y sede del Templo, empleado tanto para la ciudad literal (Mt 23:37; Lc 2:25, 41) como simbólicamente para la Jerusalén celestial (Gá 4:26; Heb 12:22). Esta grafía de forma semítica es la preferida por Lucas y Pablo, en contraste con la helenizada Ἱεροσόλυμα de Marcos y Juan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69438, 'spa', 'Oficio sacerdotal', 'Este sentido se refiere al sacerdocio como oficio, orden o sistema. Las tres apariciones forman parte de un argumento teológico concentrado sobre la insuficiencia del sistema levítico y la superioridad del sacerdocio de Cristo. Hebreos cuestiona la eficacia del sacerdocio levítico para la perfección y presenta el de Cristo como permanente e intransferible, según el orden de Melquisedec.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69439, 'spa', 'Isaí, nombre propio', 'Isaí, padre del rey David y antepasado de Jesucristo. Nombre propio que aparece en las genealogías de Jesús (Matt 1:5-6; Luke 3:32), en el sermón sinagogal de Pablo que identifica a David como hijo de Isaí (Acts 13:22) y en la profecía mesiánica de Isaiah 11:10 citada en Rom 15:12 sobre «la raíz de Isaí».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (69440, 'spa', 'Juez libertador de Israel', 'Hebrews incluye a Ἰεφθάε (11:32) entre los jueces que actuaron por fe. Jefté (Judges 11-12) fue un galaadita marginado que se convirtió en libertador de Israel frente a la opresión amonita. Su historia incluye el trágico voto y el sacrificio de su hija, pero Hebrews destaca su papel como instrumento de Dios para la justicia.');